<title>Viktor Router Audit</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:ital,wght@0,400;0,500;0,600;0,700;1,400&family=IBM+Plex+Mono:wght@400;500&display=swap">
<style>
  :root {
    --bg: #fbfafd;
    --surface: #ffffff;
    --surface-2: #f3f1f8;
    --ink: #201e2c;
    --ink-soft: #55516b;
    --ink-faint: #8b87a0;
    --line: #e4e1ee;
    --accent: #5b45e0;
    --accent-soft: #eeebfc;
    --good: #2e7d5b;
    --good-soft: #e7f3ee;
    --crit: #bb3434;
    --crit-soft: #faecec;
    --major: #a06a14;
    --major-soft: #f9f1e2;
    --minor: #5d6472;
    --minor-soft: #eef0f4;
    --code-bg: #f1eff8;
  }
  @media (prefers-color-scheme: dark) {
    :root:not([data-theme="light"]) {
      --bg: #16151d;
      --surface: #1e1c28;
      --surface-2: #26232f;
      --ink: #eae8f4;
      --ink-soft: #b3aec9;
      --ink-faint: #7d7894;
      --line: #322f40;
      --accent: #a290ff;
      --accent-soft: #2b2547;
      --good: #6fc9a3;
      --good-soft: #1d3229;
      --crit: #e57e7e;
      --crit-soft: #3c2222;
      --major: #ddab5a;
      --major-soft: #372c18;
      --minor: #a7adbb;
      --minor-soft: #282b33;
      --code-bg: #29263a;
    }
  }
  :root[data-theme="dark"] {
    --bg: #16151d;
    --surface: #1e1c28;
    --surface-2: #26232f;
    --ink: #eae8f4;
    --ink-soft: #b3aec9;
    --ink-faint: #7d7894;
    --line: #322f40;
    --accent: #a290ff;
    --accent-soft: #2b2547;
    --good: #6fc9a3;
    --good-soft: #1d3229;
    --crit: #e57e7e;
    --crit-soft: #3c2222;
    --major: #ddab5a;
    --major-soft: #372c18;
    --minor: #a7adbb;
    --minor-soft: #282b33;
    --code-bg: #29263a;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    background: var(--bg);
    color: var(--ink);
    font-family: "IBM Plex Sans", "Segoe UI", system-ui, sans-serif;
    font-size: 16px;
    line-height: 1.62;
  }
  .wrap { max-width: 900px; margin: 0 auto; padding: 48px 24px 96px; }
  header { border-bottom: 2px solid var(--accent); padding-bottom: 28px; margin-bottom: 36px; }
  .eyebrow {
    font-size: 12.5px; font-weight: 600; letter-spacing: .12em; text-transform: uppercase;
    color: var(--accent); margin: 0 0 10px;
  }
  h1 { font-size: 36px; font-weight: 700; line-height: 1.15; margin: 0 0 12px; letter-spacing: -.01em; text-wrap: balance; }
  .meta { color: var(--ink-faint); font-size: 14px; margin: 0; }
  h2 {
    font-size: 23px; font-weight: 700; letter-spacing: -.01em; margin: 56px 0 6px;
    text-wrap: balance;
  }
  h2 .sec-no { color: var(--accent); font-variant-numeric: tabular-nums; margin-right: 10px; }
  .sec-sub { color: var(--ink-soft); margin: 0 0 20px; font-size: 15.5px; }
  h3 { font-size: 17px; font-weight: 600; margin: 30px 0 8px; }
  p { margin: 0 0 14px; max-width: 72ch; }
  code, .file {
    font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
    font-size: .86em; background: var(--code-bg); border-radius: 4px; padding: 1px 5px;
  }
  a { color: var(--accent); }
  ul, ol { margin: 0 0 16px; padding-left: 24px; }
  li { margin-bottom: 7px; max-width: 70ch; }
  strong { font-weight: 600; }

  /* verdict band */
  .verdict {
    background: var(--surface); border: 1px solid var(--line); border-radius: 10px;
    padding: 22px 26px; margin: 0 0 12px;
  }
  .verdict p { max-width: none; }
  .verdict p:last-child { margin-bottom: 0; }
  .stat-row { display: flex; flex-wrap: wrap; gap: 12px; margin: 24px 0 8px; }
  .stat {
    flex: 1 1 150px; background: var(--surface); border: 1px solid var(--line); border-radius: 10px;
    padding: 14px 16px;
  }
  .stat .n { font-size: 26px; font-weight: 700; font-variant-numeric: tabular-nums; line-height: 1.2; }
  .stat .l { font-size: 12.5px; color: var(--ink-soft); letter-spacing: .04em; text-transform: uppercase; font-weight: 600; }
  .stat.crit .n { color: var(--crit); }
  .stat.major .n { color: var(--major); }
  .stat.minor .n { color: var(--minor); }
  .stat.good .n { color: var(--good); }

  /* pills */
  .pill {
    display: inline-block; font-size: 11.5px; font-weight: 700; letter-spacing: .08em;
    text-transform: uppercase; border-radius: 999px; padding: 2px 10px; vertical-align: 2px;
  }
  .pill.crit { background: var(--crit-soft); color: var(--crit); }
  .pill.major { background: var(--major-soft); color: var(--major); }
  .pill.minor { background: var(--minor-soft); color: var(--minor); }
  .pill.good { background: var(--good-soft); color: var(--good); }
  .pill.gap { background: var(--accent-soft); color: var(--accent); }

  /* findings */
  .finding {
    background: var(--surface); border: 1px solid var(--line); border-left: 4px solid var(--minor);
    border-radius: 8px; padding: 18px 22px; margin: 0 0 14px;
  }
  .finding.crit { border-left-color: var(--crit); }
  .finding.major { border-left-color: var(--major); }
  .finding h4 { margin: 0 0 8px; font-size: 16px; font-weight: 600; line-height: 1.4; }
  .finding h4 .fid { color: var(--ink-faint); font-family: "IBM Plex Mono", monospace; font-size: 13px; margin-right: 8px; }
  .finding p { font-size: 15px; color: var(--ink-soft); max-width: none; }
  .finding p:last-child { margin-bottom: 0; }
  .finding .fix { color: var(--ink); }
  .finding .fix::before { content: "Fix — "; font-weight: 600; color: var(--good); }

  /* tables */
  .tbl-scroll { overflow-x: auto; border: 1px solid var(--line); border-radius: 10px; background: var(--surface); margin-bottom: 18px; }
  table { border-collapse: collapse; width: 100%; font-size: 14.5px; }
  th {
    text-align: left; font-size: 12px; letter-spacing: .07em; text-transform: uppercase;
    color: var(--ink-soft); font-weight: 600; padding: 12px 16px; border-bottom: 1px solid var(--line);
    background: var(--surface-2); white-space: nowrap;
  }
  td { padding: 11px 16px; border-bottom: 1px solid var(--line); vertical-align: top; }
  tr:last-child td { border-bottom: none; }
  td.num { font-variant-numeric: tabular-nums; white-space: nowrap; }

  /* action plan */
  .plan { counter-reset: step; list-style: none; padding: 0; }
  .plan li {
    counter-increment: step; position: relative; padding: 14px 18px 14px 58px; margin-bottom: 10px;
    background: var(--surface); border: 1px solid var(--line); border-radius: 8px; max-width: none;
  }
  .plan li::before {
    content: counter(step); position: absolute; left: 16px; top: 14px;
    width: 28px; height: 28px; border-radius: 50%; background: var(--accent-soft); color: var(--accent);
    font-weight: 700; font-size: 14px; display: flex; align-items: center; justify-content: center;
    font-variant-numeric: tabular-nums;
  }
  .plan .effort { font-size: 12px; font-weight: 600; color: var(--ink-faint); text-transform: uppercase; letter-spacing: .06em; margin-left: 8px; white-space: nowrap; }
  .plan p { font-size: 14.5px; color: var(--ink-soft); margin: 4px 0 0; max-width: none; }

  .note {
    background: var(--surface-2); border-radius: 8px; padding: 14px 18px; font-size: 14.5px;
    color: var(--ink-soft); margin-bottom: 16px;
  }
  .note p { max-width: none; }
  .note p:last-child { margin-bottom: 0; }

  .toc { display: flex; flex-wrap: wrap; gap: 8px; margin: 18px 0 0; padding: 0; list-style: none; }
  .toc li { margin: 0; }
  .toc a {
    display: inline-block; font-size: 13.5px; font-weight: 500; text-decoration: none;
    background: var(--surface); border: 1px solid var(--line); border-radius: 999px; padding: 5px 14px;
    color: var(--ink-soft);
