function ranksOf(vals) { // average-rank percentiles in [0,1]
  const n = vals.length, idx = Array.from({length: n}, (_, i) => i).sort((a, b) => vals[a] - vals[b]);
  const out = new Float64Array(n); let i = 0;
  while (i < n) {
    let j = i; while (j + 1 < n && vals[idx[j + 1]] === vals[idx[i]]) j++;
    const avg = (i + j) / 2; for (let k = i; k <= j; k++) out[idx[k]] = avg;
    i = j + 1;
  }
  const mx = n - 1 || 1; for (let k = 0; k < n; k++) out[k] /= mx;
  return out;
}

input.new_string:
function ranksOf(vals) { // right-ECDF ranks — EXACTLY rank_utils.ecdf_ranks in Python
  const n = vals.length, sorted = Array.from(vals).sort((a, b) => a - b);
  const out = new Float64Array(n);
  if (!n || sorted[0] === sorted[n - 1]) { out.fill(0.5); return out; } // constant -> neutral
  for (let k = 0; k < n; k++) {
    let lo = 0, hi = n; // upper_bound(sorted, vals[k])
    while (lo < hi) { const m = (lo + hi) >> 1; if (sorted[m] <= vals[k]) lo = m + 1; else hi = m; }
    out[k] = lo / n;
  }
  return out;
}

