// FAIR-COMPARISON GRADING for the logged-dispatch point: tool errors and retry
// streaks also drove the tier inference, so a model that logged errors would be
// assigned a low tier AND have its trajectories graded harder — mechanically
// depressing logged served%. For this one comparison, difficulty is graded
// with those two metrics zeroed (weights renormalized) and the error override off.
function gradeStruggleFree() {
  const w = {...state.evW, n_tool_errors: 0, max_repeat_streak: 0};
  let tw = 0; for (const k in w) tw += w[k];
  const scores = new Float64Array(N);
  for (let i = 0; i < N; i++) {
    const rk = R[i].evRank; let s = 0;
    M.evNames.forEach((k, c) => s += (w[k] || 0) * rk[c]);
    scores[i] = s / (tw || 1);
  }
  const { tiers } = cutTiers(scores, state.evCuts);
  for (let i = 0; i < N; i++)
    if (R[i].ev.n_tool_calls >= state.ov.tool_calls_t3) tiers[i] = 3;
