143	function quantile(sorted,q){const x=q*(sorted.length-1),lo=Math.floor(x),hi=Math.ceil(x);
144	  return sorted[lo]+(sorted[hi]-sorted[lo])*(x-lo)}
145	const evScores=(()=>{const w=DEF.evWeights;let tw=0;for(const k in w)tw+=w[k];
146	  return R.map(r=>{let s=0;M.evNames.forEach((k,c)=>s+=(w[k]||0)*r.evRank[c]);return s/tw})})();
