  front.timer=setInterval(()=>{
    front.cur+=front.dir;
    if(front.cur<=0){front.dir=1;bounced=true}
    if(bounced&&front.cur>=front.opIdx){front.cur=front.opIdx;stopReplay()}
    drawFrontier();
